    literals = set()
    clauses = []
    new_vars = {}

    def get_new_var():
        nonlocal new_vars
        while True:
            var = random.randint(1, 2 * len(cnf))
            if var not in new_vars.values():
                new_vars[var] = len(new_vars) + 1
                return var

    for i, clause in enumerate(cnf):
        literals.update(clause)
        new_var = get_new_var()
